(6253189, 924627, 61084, '<td valign="top">This doesn''t really have a "from the ground up" feel to it. Your camera may have been low to the ground but you basically shot a normal landscape. Not voting until later in the week.</td>', 'This doesn''t really have a "from the ground up" feel to it. Your camera may have been low to the ground but you basically shot a normal landscape. Not voting until later in the week.', '2010-12-13 21:16:38.000000', NULL, 1),
(6253190, 924829, 61084, '<td valign="top">I like the building, perspective and texture, but the sky is darker than I feel it should be. It''s pushing black in spots on my calibrated monitors and doesn''t look as natural as I would have liked. Not voting until later in the week.</td>', 'I like the building, perspective and texture, but the sky is darker than I feel it should be. It''s pushing black in spots on my calibrated monitors and doesn''t look as natural as I would have liked. Not voting until later in the week.', '2010-12-13 21:18:31.000000', NULL, 1),
(6253191, 924874, 96751, '<td valign="top">I love the feeling of possibilities and adventure that this image provokes in me.  There is ambition in reaching for the unknown, and even to have the forethought to document the journey.</td>', 'I love the feeling of possibilities and adventure that this image provokes in me.  There is ambition in reaching for the unknown, and even to have the forethought to document the journey.', '2010-12-13 21:19:00.000000', NULL, 1),
