(6256690, 924801, 121789, '<td valign="top">the season, the vintage and the processing all match up well - 8</td>', 'the season, the vintage and the processing all match up well - 8', '2010-12-18 08:23:21.000000', NULL, 1),
(6256691, 924866, 11769, '<td valign="top">Good composition</td>', 'Good composition', '2010-12-18 08:24:28.000000', NULL, 1),
(6256692, 924709, 121789, '<td valign="top">Great subject, tricky light and crooked. 5</td>', 'Great subject, tricky light and crooked. 5', '2010-12-18 08:24:40.000000', NULL, 1),
(6256693, 924610, 121789, '<td valign="top">+1 for a clever title!  8</td>', '+1 for a clever title!  8', '2010-12-18 08:25:58.000000', NULL, 1),
(6256694, 924799, 11769, '<td valign="top">Like that pinky</td>', 'Like that pinky', '2010-12-18 08:26:44.000000', NULL, 1),
(6256695, 924889, 121789, '<td valign="top">This has a very "Whoville" feel - helps make fit the off kilter capture! 7</td>', 'This has a very "Whoville" feel - helps make fit the off kilter capture! 7', '2010-12-18 08:28:17.000000', NULL, 1),
(6256696, 924623, 11769, '<td valign="top">From people jumping out of windows? Like.</td>', 'From people jumping out of windows? Like.', '2010-12-18 08:30:01.000000', NULL, 1),
(6256697, 924885, 11769, '<td valign="top">Beautiful</td>', 'Beautiful', '2010-12-18 08:30:19.000000', NULL, 1),
(6256698, 924877, 11769, '<td valign="top">Birds are a nice touch</td>', 'Birds are a nice touch', '2010-12-18 08:31:06.000000', NULL, 1),
(6256699, 924298, 11769, '<td valign="top">:)</td>', ':)', '2010-12-18 08:31:34.000000', NULL, 1),
(6256704, 924750, 121789, '<td valign="top">A very "from the beginning of time" feel - I like it - 8</td>', 'A very "from the beginning of time" feel - I like it - 8', '2010-12-18 08:43:53.000000', NULL, 1),
(6256706, 924875, 121789, '<td valign="top">The gray sky, crisp snow and contemplation of the few seem to fit the subject very well. I would like to know more about the sculpture . . . 8</td>', 'The gray sky, crisp snow and contemplation of the few seem to fit the subject very well. I would like to know more about the sculpture . . . 8', '2010-12-18 08:48:27.000000', NULL, 1),
(6256712, 924668, 121789, '<td valign="top">The title ties this all together and makes me think . . . stormy sky, muted colors, battered symbol and the willingness to allow it to fly in tatters . . . divided, for sure - nearly torn to shreds. 8</td>', 'The title ties this all together and makes me think . . . stormy sky, muted colors, battered symbol and the willingness to allow it to fly in tatters . . . divided, for sure - nearly torn to shreds. 8', '2010-12-18 08:54:34.000000', NULL, 1),
(6256715, 924809, 121789, '<td valign="top">WOAH! Part nightmare, part fantasy - I just don''t know where this is going! 7</td>', 'WOAH! Part nightmare, part fantasy - I just don''t know where this is going! 7', '2010-12-18 08:56:16.000000', NULL, 1),
(6256716, 924670, 121789, '<td valign="top">GIggity - 6</td>', 'GIggity - 6', '2010-12-18 08:57:27.000000', NULL, 1),
(6256718, 924004, 121789, '<td valign="top">Interesting perspective, but the life of an alpha male from high school sports to present day have underscored a much different meaning for "fromunda" for me than your picture represents! +1 for nostalgia - 8</td>', 'Interesting perspective, but the life of an alpha male from high school sports to present day have underscored a much different meaning for "fromunda" for me than your picture represents! +1 for nostalgia - 8', '2010-12-18 08:59:40.000000', NULL, 1),
(6256719, 924836, 121789, '<td valign="top">This so perfectly captures my own dream and it is more vivid with the colors and precision and perspective - 10 and a favorite!</td>', 'This so perfectly captures my own dream and it is more vivid with the colors and precision and perspective - 10 and a favorite!', '2010-12-18 09:01:29.000000', NULL, 1),
(6256720, 924777, 121789, '<td valign="top">Nice capture! The title made me look closer and introduced more levels - very well done!!  9</td>', 'Nice capture! The title made me look closer and introduced more levels - very well done!!  9', '2010-12-18 09:04:55.000000', NULL, 1),
(6256723, 924826, 121789, '<td valign="top">This portrays a warm optimism - 9</td>', 'This portrays a warm optimism - 9', '2010-12-18 09:06:33.000000', NULL, 1),
(6256724, 924565, 121789, '<td valign="top">Interesting perspective and image. The title spins this into a whole ''nother dimension of thought and perception - 9</td>', 'Interesting perspective and image. The title spins this into a whole ''nother dimension of thought and perception - 9', '2010-12-18 09:07:59.000000', NULL, 1),
(6256726, 924829, 121789, '<td valign="top">Hard. Cold. Stern. Unfeeling. Corporate. +1 for creative title - 8</td>', 'Hard. Cold. Stern. Unfeeling. Corporate. +1 for creative title - 8', '2010-12-18 09:10:11.000000', NULL, 1),
(6256874, 924777, 115814, '<td valign="top">Not voting, but I really like this. I hope it does well.</td>', 'Not voting, but I really like this. I hope it does well.', '2010-12-18 14:33:27.000000', NULL, 1),
(6256875, 924525, 115814, '<td valign="top">Not voting here, but this one catches my eye. The post-processing is certainly extreme and dramatic, not sure if this couldn''t have been just as good, or better with less tweaking, though.</td>', 'Not voting here, but this one catches my eye. The post-processing is certainly extreme and dramatic, not sure if this couldn''t have been just as good, or better with less tweaking, though.', '2010-12-18 14:36:19.000000', NULL, 1),
(6256876, 924762, 115814, '<td valign="top">Not voting here, but for me, this manages to meet the theme and tell a story. Definitely one of my favorites!</td>', 'Not voting here, but for me, this manages to meet the theme and tell a story. Definitely one of my favorites!', '2010-12-18 14:38:25.000000', NULL, 1),
(6256919, 924455, 76335, '<td valign="top">This is the cliche ground-up shot. High contast black and white would be my preference for something like this. The tones here don''t hold much interest. It''s more about the patterns and rhythm and textures. I do like the composition and the clouds (and cloud reflections) add good counterpoint.</td>', 'This is the cliche ground-up shot. High contast black and white would be my preference for something like this. The tones here don''t hold much interest. It''s more about the patterns and rhythm and textures. I do like the composition and the clouds (and cloud reflections) add good counterpoint.', '2010-12-18 16:54:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6256921, 924630, 76335, '<td valign="top">Good idea, nicely framed. Faces are a little dark.</td>', 'Good idea, nicely framed. Faces are a little dark.', '2010-12-18 16:54:35.000000', NULL, 1),
(6256923, 924709, 76335, '<td valign="top">Great shadows, the dark sky helps. I appreciate that it isn''t centered and symmetric.</td>', 'Great shadows, the dark sky helps. I appreciate that it isn''t centered and symmetric.', '2010-12-18 16:55:20.000000', NULL, 1),
(6256924, 924738, 76335, '<td valign="top">Very imposing.</td>', 'Very imposing.', '2010-12-18 16:56:06.000000', NULL, 1),
(6256970, 924750, 76335, '<td valign="top">This is interesting. The shallow DOF gives the root a slimy look as the eye follows it toward the tree.</td>', 'This is interesting. The shallow DOF gives the root a slimy look as the eye follows it toward the tree.', '2010-12-18 18:18:07.000000', NULL, 1),
(6256971, 924799, 76335, '<td valign="top">Creative. Almost looks like a charcoal drawing. Well done.</td>', 'Creative. Almost looks like a charcoal drawing. Well done.', '2010-12-18 18:18:38.000000', NULL, 1),
(6256973, 924866, 76335, '<td valign="top">Quite a surprising point of view. A bold statement too.</td>', 'Quite a surprising point of view. A bold statement too.', '2010-12-18 18:22:22.000000', NULL, 1),
(6256987, 924680, 18367, '<td valign="top">I am not normally a big fan of fisheye lens images, but this one truly rocks.  I would not be surprised to see this on the front page.  <br/> <br/>Good luck in the challenge.</td>', 'I am not normally a big fan of fisheye lens images, but this one truly rocks.  I would not be surprised to see this on the front page.   Good luck in the challenge.', '2010-12-18 18:34:25.000000', NULL, 1),
(6257024, 924876, 23484, '<td valign="top">Outstanding capture. Great angles.</td>', 'Outstanding capture. Great angles.', '2010-12-18 19:47:10.000000', NULL, 1),
(6257025, 924891, 23484, '<td valign="top">Love the heavy grain.</td>', 'Love the heavy grain.', '2010-12-18 19:47:32.000000', NULL, 1),
(6257172, 924750, 115232, '<td valign="top">to me this photo fills the brief perfectly The tree takes from the ground and grows up We are looking from the ground up. I like the shallow depth of field as it ads to the impression the we are tiny looking up</td>', 'to me this photo fills the brief perfectly The tree takes from the ground and grows up We are looking from the ground up. I like the shallow depth of field as it ads to the impression the we are tiny looking up', '2010-12-19 00:03:30.000000', NULL, 1),
(6257235, 924204, 123789, '<td valign="top">Wow, it is an amzing photo</td>', 'Wow, it is an amzing photo', '2010-12-19 06:23:38.000000', NULL, 1),
(6257255, 924854, 48954, '<td valign="top">surreal! 8</td>', 'surreal! 8', '2010-12-19 07:40:43.000000', NULL, 1),
(6257273, 924680, 96464, '<td valign="top">nice</td>', 'nice', '2010-12-19 08:17:53.000000', NULL, 1),
(6257330, 924826, 76335, '<td valign="top">Soft and subtle. And a kaleidoscopic green sun to boot.</td>', 'Soft and subtle. And a kaleidoscopic green sun to boot.', '2010-12-19 10:49:46.000000', NULL, 1),
(6257331, 924852, 76335, '<td valign="top">Great fiction! (Or is it?)</td>', 'Great fiction! (Or is it?)', '2010-12-19 10:50:18.000000', NULL, 1),
(6257342, 924072, 27399, '<td valign="top">Great composition and capture.</td>', 'Great composition and capture.', '2010-12-19 11:30:22.000000', NULL, 1),
(6257343, 924625, 27399, '<td valign="top">I like your choice to make the tree go straight up, even though it throws the horizon off skew.  The peak through the "elbow" near the base is a good touch.</td>', 'I like your choice to make the tree go straight up, even though it throws the horizon off skew.  The peak through the "elbow" near the base is a good touch.', '2010-12-19 11:32:36.000000', NULL, 1),
(6257346, 924670, 124962, '<td valign="top">very imaginative</td>', 'very imaginative', '2010-12-19 11:33:25.000000', NULL, 1),
(6257349, 924788, 27399, '<td valign="top">Good choice with b/w on this.  Good job framing the lines and using the reflection to give it another dimension feel to it.</td>', 'Good choice with b/w on this.  Good job framing the lines and using the reflection to give it another dimension feel to it.', '2010-12-19 11:35:13.000000', NULL, 1),
(6257354, 924806, 27399, '<td valign="top">I like the angle, it definitely exaggerates the curves of the hall and a good sense of depth. Your fading line to the clock reading 16:05 is a nice touch.</td>', 'I like the angle, it definitely exaggerates the curves of the hall and a good sense of depth. Your fading line to the clock reading 16:05 is a nice touch.', '2010-12-19 11:38:22.000000', NULL, 1),
(6257357, 924667, 27399, '<td valign="top">Love the concept and it captures the theme of the challenge perfectly.</td>', 'Love the concept and it captures the theme of the challenge perfectly.', '2010-12-19 11:40:20.000000', NULL, 1),
(6257359, 924393, 27399, '<td valign="top">The idea is great and the delivery of that idea is well done, from the framing to the exposure/processing.</td>', 'The idea is great and the delivery of that idea is well done, from the framing to the exposure/processing.', '2010-12-19 11:42:28.000000', NULL, 1),
(6257360, 924777, 27399, '<td valign="top">Very creative capture and title.  The angle gives it an almost surreal feeling.  I like that people are looking down, completely oblivious to what''s above them.  Good job.</td>', 'Very creative capture and title.  The angle gives it an almost surreal feeling.  I like that people are looking down, completely oblivious to what''s above them.  Good job.', '2010-12-19 11:44:43.000000', NULL, 1),
(6257361, 924638, 27399, '<td valign="top">Non-traditional way of shooting the Needle: I like it!  The image says a lot about the Seattle area: trendy(?), beautiful, modern, goofy, etc.  Well done.</td>', 'Non-traditional way of shooting the Needle: I like it!  The image says a lot about the Seattle area: trendy(?), beautiful, modern, goofy, etc.  Well done.', '2010-12-19 11:48:56.000000', NULL, 1),
(6257363, 924750, 27399, '<td valign="top">Very nice composition and choice of focal point.  The light on the tree still brings our attention there instead of it just being an out of focus part of the shot.  Good job, hope it does well overall!</td>', 'Very nice composition and choice of focal point.  The light on the tree still brings our attention there instead of it just being an out of focus part of the shot.  Good job, hope it does well overall!', '2010-12-19 11:53:44.000000', NULL, 1),
(6257364, 924623, 27399, '<td valign="top">I like that you captured all the elements of what''s going on from the ground up: people that work in the buildings, people that build them, one being constructed, and the tools to build them (the crane).  Definitely reflects from the ground up.</td>', 'I like that you captured all the elements of what''s going on from the ground up: people that work in the buildings, people that build them, one being constructed, and the tools to build them (the crane).  Definitely reflects from the ground up.', '2010-12-19 11:55:37.000000', NULL, 1),
(6257365, 924452, 27399, '<td valign="top">Very unique shot to capture that "eye" effect in the scene. Referencing the eye overtly makes the viewer look at the whole composition as such which draws out the detail of all the small branches.  Well done.</td>', 'Very unique shot to capture that "eye" effect in the scene. Referencing the eye overtly makes the viewer look at the whole composition as such which draws out the detail of all the small branches.  Well done.', '2010-12-19 12:01:32.000000', NULL, 1),
(6257403, 924439, 64086, '<td valign="top">Amazing pov. Love the fur like the sky and the sky like the fur. My eye is perfectly and unconditionally drawn to the mouth. Incredible shot.</td>', 'Amazing pov. Love the fur like the sky and the sky like the fur. My eye is perfectly and unconditionally drawn to the mouth. Incredible shot.', '2010-12-19 13:20:28.000000', NULL, 1),
(6257414, 924773, 111937, '<td valign="top">Mark on 2nd and 3rd lamp bother''s little</td>', 'Mark on 2nd and 3rd lamp bother''s little', '2010-12-19 13:47:02.000000', NULL, 1),
(6257416, 924600, 111937, '<td valign="top">I like this a lot ..will get a ribbon for sure!!</td>', 'I like this a lot ..will get a ribbon for sure!!', '2010-12-19 13:52:35.000000', NULL, 1),
(6257418, 924680, 111937, '<td valign="top">nicely captured ..</td>', 'nicely captured ..', '2010-12-19 13:54:08.000000', NULL, 1),
(6257462, 924850, 59796, '<td valign="top">A ribbon winner in my book. The crisp burst/flare, the blue/gold filter, the still visible details on the plane - all add up to a very nice perspective picture complemented by a nice title. The border''s distracting a little bit, especially considering that the clouds already form a natural border for the picture.</td>', 'A ribbon winner in my book. The crisp burst/flare, the blue/gold filter, the still visible details on the plane - all add up to a very nice perspective picture complemented by a nice title. The border''s distracting a little bit, especially considering that the clouds already form a natural border for the picture.', '2010-12-19 15:43:36.000000', NULL, 1),
(6257464, 924600, 59796, '<td valign="top">A ribbon winner in my book. Good sepia conversion, nice symmetric(almost) patterns and a unique perpsective for sure. Since I don''t know of any store that sells street lights - I''m very curious as to where this is :)</td>', 'A ribbon winner in my book. Good sepia conversion, nice symmetric(almost) patterns and a unique perpsective for sure. Since I don''t know of any store that sells street lights - I''m very curious as to where this is :)', '2010-12-19 15:45:41.000000', NULL, 1),
(6257466, 924723, 59796, '<td valign="top">Ha! Good observation, capture, and title. Nice patterns. The B/W conversion is a good idea too.</td>', 'Ha! Good observation, capture, and title. Nice patterns. The B/W conversion is a good idea too.', '2010-12-19 15:48:45.000000', NULL, 1),
(6257469, 924859, 59796, '<td valign="top">Phew! An unusual sight for sure - nicely lit up and very well captured. The white in the border is jarring though - maybe instead of a white if it were dull yellow it might''ve gelled better with the picture.</td>', 'Phew! An unusual sight for sure - nicely lit up and very well captured. The white in the border is jarring though - maybe instead of a white if it were dull yellow it might''ve gelled better with the picture.', '2010-12-19 15:51:11.000000', NULL, 1),
(6257472, 924298, 59796, '<td valign="top">DNMC - This picture''s not looking up from the Ground, it''s looking up from the car floorboard.<br/> <br/>:P Just pulling your leg - Wonderful idea, unique perspective, well captured and good conversion to B/W.</td>', 'DNMC - This picture''s not looking up from the Ground, it''s looking up from the car floorboard. :P Just pulling your leg - Wonderful idea, unique perspective, well captured and good conversion to B/W.', '2010-12-19 15:58:37.000000', NULL, 1),
(6257474, 924839, 59796, '<td valign="top">I see the rear wheels coming down for landing - cool! A spot of color on the underbody of the plane adds interest to the drab B/W weather. Interesting diagonal composition and perfect amount of negative space all around for the plane to move into. Very nicely done.</td>', 'I see the rear wheels coming down for landing - cool! A spot of color on the underbody of the plane adds interest to the drab B/W weather. Interesting diagonal composition and perfect amount of negative space all around for the plane to move into. Very nicely done.', '2010-12-19 16:01:28.000000', NULL, 1),
(6257475, 924829, 59796, '<td valign="top">Almost like an angry/evil corporation :) Good sharp lines and interesting warm/cold hues on either  side of the building - nice capture/post.</td>', 'Almost like an angry/evil corporation :) Good sharp lines and interesting warm/cold hues on either  side of the building - nice capture/post.', '2010-12-19 16:03:38.000000', NULL, 1),
(6257476, 924452, 59796, '<td valign="top">Very cool! The right side of the pic is distracting from a very nice image and perspective. Makes me want to look at it in full resolution and all the details on those dead branches at the top will make it look sinister :)</td>', 'Very cool! The right side of the pic is distracting from a very nice image and perspective. Makes me want to look at it in full resolution and all the details on those dead branches at the top will make it look sinister :)', '2010-12-19 16:08:51.000000', NULL, 1),
(6257477, 924565, 59796, '<td valign="top">Nice bird! The pole is distracting a bit from the bird - maybe crop it off?<br/> <br/>:P Just kidding - nice capture with great lines and an excellent conversion to B/W - very moody.</td>', 'Nice bird! The pole is distracting a bit from the bird - maybe crop it off? :P Just kidding - nice capture with great lines and an excellent conversion to B/W - very moody.', '2010-12-19 16:10:46.000000', NULL, 1),
(6257478, 924852, 59796, '<td valign="top">Scary!<br/> <br/>Amazing idea - very well captured/processed. Great title too! A ribbon winner in my book.</td>', 'Scary! Amazing idea - very well captured/processed. Great title too! A ribbon winner in my book.', '2010-12-19 16:11:45.000000', NULL, 1),
(6257480, 924854, 59796, '<td valign="top">Nice little fan you have there :) Very well captured and titled.</td>', 'Nice little fan you have there :) Very well captured and titled.', '2010-12-19 16:12:30.000000', NULL, 1),
(6257483, 924798, 59796, '<td valign="top">Unusual composition of an interesting architecture. The wonderful lighting and the gold hues contrast very well with the night sky - although there''s quite a bit of noise showing up in the blues.</td>', 'Unusual composition of an interesting architecture. The wonderful lighting and the gold hues contrast very well with the night sky - although there''s quite a bit of noise showing up in the blues.', '2010-12-19 16:15:19.000000', NULL, 1),
(6257484, 924771, 59796, '<td valign="top">Great idea! I take it you have a very good tripod - the lines are perfectly straight without a niggle. Nice conversion to B/W as well. My top 10.</td>', 'Great idea! I take it you have a very good tripod - the lines are perfectly straight without a niggle. Nice conversion to B/W as well. My top 10.', '2010-12-19 16:17:02.000000', NULL, 1),
(6257486, 924204, 59796, '<td valign="top">Phew! Very very cool architecture nicely captured. Very curious as to what/where this is.</td>', 'Phew! Very very cool architecture nicely captured. Very curious as to what/where this is.', '2010-12-19 16:18:21.000000', NULL, 1),
(6257487, 924489, 59796, '<td valign="top">Very nice idea - the warm tones of the lighting on the tree match with the warm sky and contrast nicely with the cool star trails. The border (especially the white lines) are quite distracting though.</td>', 'Very nice idea - the warm tones of the lighting on the tree match with the warm sky and contrast nicely with the cool star trails. The border (especially the white lines) are quite distracting though.', '2010-12-19 16:20:27.000000', NULL, 1),
(6257490, 924811, 59796, '<td valign="top">Beautiful patterns on the ferns - match up well with the delightful cloud pattern in the sky. I would''ve liked a little more breathing space for the ferns on the left and right. Loving the picture - my top 10 for sure.</td>', 'Beautiful patterns on the ferns - match up well with the delightful cloud pattern in the sky. I would''ve liked a little more breathing space for the ferns on the left and right. Loving the picture - my top 10 for sure.', '2010-12-19 16:22:23.000000', NULL, 1),
(6257491, 924799, 59796, '<td valign="top">hehe - I wouldn''t write on the lens if I were you :P<br/>Great idea, well captured and nicely converted to B/W - loving the noise grain on the hand.</td>', 'hehe - I wouldn''t write on the lens if I were you :PGreat idea, well captured and nicely converted to B/W - loving the noise grain on the hand.', '2010-12-19 16:24:12.000000', NULL, 1),
(6257492, 924680, 59796, '<td valign="top">Good competition going on there and the witty title enhances the picture and changes my perception of it. Great capture to begin with and a very interesting sky to boot.</td>', 'Good competition going on there and the witty title enhances the picture and changes my perception of it. Great capture to begin with and a very interesting sky to boot.', '2010-12-19 16:25:31.000000', NULL, 1),
(6257494, 924746, 59796, '<td valign="top">Nice! Very well captured and processed. Love the diagonal composition and the intentional asymmetry. Probably didn''t need the border, but a good border nevertheless.</td>', 'Nice! Very well captured and processed. Love the diagonal composition and the intentional asymmetry. Probably didn''t need the border, but a good border nevertheless.', '2010-12-19 16:27:31.000000', NULL, 1),
(6257496, 924826, 59796, '<td valign="top">Beautiful composition and title. Love it.</td>', 'Beautiful composition and title. Love it.', '2010-12-19 16:31:24.000000', NULL, 1),
(6257550, 924219, 65234, '<td valign="top">Feels claustrophically small and crowded.</td>', 'Feels claustrophically small and crowded.', '2010-12-19 18:06:57.000000', NULL, 1),
(6257553, 924627, 65234, '<td valign="top">Very pretty, peaceful image.  I think for this challenge I''d score it higher if the camera were tilted more obviously upward, but I do like it.</td>', 'Very pretty, peaceful image.  I think for this challenge I''d score it higher if the camera were tilted more obviously upward, but I do like it.', '2010-12-19 18:10:01.000000', NULL, 1),
(6257563, 924439, 65234, '<td valign="top">Love the light framing him (her?).  A mini-Cujo ;-)</td>', 'Love the light framing him (her?).  A mini-Cujo ;-)', '2010-12-19 18:22:26.000000', NULL, 1),
(6257566, 924850, 65234, '<td valign="top">Gorgeous sunburst!  Not sure if I would have kept the yellow or desaturated it.  Or maybe punted and gone with B&amp;W.  Still, a stunning job on the exposure IMO; there''s even another little sunburst on a reflection on the plane!</td>', 'Gorgeous sunburst!  Not sure if I would have kept the yellow or desaturated it.  Or maybe punted and gone with B&W.  Still, a stunning job on the exposure IMO; there''s even another little sunburst on a reflection on the plane!', '2010-12-19 18:24:19.000000', NULL, 1),
(6257567, 924854, 65234, '<td valign="top">Sorry about that.  Interesting ceiling fan, though ;-)</td>', 'Sorry about that.  Interesting ceiling fan, though ;-)', '2010-12-19 18:24:23.000000', NULL, 1),
(6257568, 924600, 65234, '<td valign="top">Almost an abstract feeling to the pattern.   Pretty cool perspective.</td>', 'Almost an abstract feeling to the pattern.   Pretty cool perspective.', '2010-12-19 18:24:27.000000', NULL, 1),
(6257569, 924695, 108069, '<td valign="top">Nice. Good focus, great colors.</td>', 'Nice. Good focus, great colors.', '2010-12-19 18:24:40.000000', NULL, 1),
(6257570, 924828, 65234, '<td valign="top">Nice shapes here.</td>', 'Nice shapes here.', '2010-12-19 18:24:45.000000', NULL, 1),
(6257571, 924680, 65234, '<td valign="top">Reminds me of a cinematic supernatural storm up there in the sky.</td>', 'Reminds me of a cinematic supernatural storm up there in the sky.', '2010-12-19 18:24:56.000000', NULL, 1),
(6257572, 924690, 65234, '<td valign="top">Love the mood in this one.  She seems to have no interest in posing for the camera, but something surely has her attention over there, out of my sight.  She looks carefree with those dangling bare feet, definitely not afraid to get dirty.  Good for her!</td>', 'Love the mood in this one.  She seems to have no interest in posing for the camera, but something surely has her attention over there, out of my sight.  She looks carefree with those dangling bare feet, definitely not afraid to get dirty.  Good for her!', '2010-12-19 18:25:09.000000', NULL, 1),
(6257573, 924771, 108069, '<td valign="top">Nice pattern. Great lines.</td>', 'Nice pattern. Great lines.', '2010-12-19 18:25:29.000000', NULL, 1),
